import '../models/models.dart';

/// A short label saying WHY something was recommended.
///
/// Tags are generated from the same facts the ranking used, so they explain
/// a decision rather than decorate it. Nothing is generated by a model, and
/// the same inputs always produce the same tags in the same order.
class RecommendationTag {
  const RecommendationTag(this.label, this.why);

  /// Shown on screen: "Lat Priority", "Vertical Pull".
  final String label;

  /// One sentence for a tooltip or a detail line.
  final String why;

  @override
  String toString() => label;

  @override
  bool operator ==(Object other) =>
      other is RecommendationTag && other.label == label;

  @override
  int get hashCode => label.hashCode;
}

/// Tags for a whole program: what it is for and how it is shaped.
List<RecommendationTag> programTags({
  required TrainingGoal goal,
  required TrainingFocus focus,
  required int daysPerWeek,
  required List<MuscleGroup> priorityMuscles,
  required SessionDuration sessionDuration,
}) {
  return [
    RecommendationTag(
      _goalLabel(goal),
      'Built for your goal to '
      '${goal.label.toLowerCase()}.',
    ),
    RecommendationTag(
      '$daysPerWeek days/week',
      'Matches the training frequency in your profile.',
    ),
    if (focus != TrainingFocus.fullBody && focus != TrainingFocus.chooseMuscles)
      RecommendationTag(
        '${focus.label} emphasis',
        'You chose to focus on ${focus.label.toLowerCase()}.',
      ),
    for (final muscle in priorityMuscles.take(2))
      RecommendationTag(
        '${muscle.label} priority',
        '${muscle.label} is one of the muscles you singled out, so it is '
            'trained earlier and more often.',
      ),
    RecommendationTag(
      sessionDuration.label,
      'Each session is sized to fit ${sessionDuration.label}.',
    ),
  ];
}

/// Tags for one session: what it trains and what it leads with.
List<RecommendationTag> workoutTags({
  required String name,
  required List<MuscleGroup> sessionMuscles,
  required List<MuscleGroup> priorityMuscles,
  required SessionDuration sessionDuration,
}) {
  final regions = sessionMuscles.map((m) => m.region).toSet();
  final groups = sessionMuscles.map((m) => m.movementGroup).toSet();

  return [
    if (regions.length == 1)
      RecommendationTag(
        regions.single.label,
        'Every exercise here trains the ${regions.single.label.toLowerCase()}.',
      ),
    if (groups.length == 1 && groups.single != MovementGroup.neither)
      RecommendationTag(
        '${groups.single.label} emphasis',
        'This session is built around ${groups.single.label.toLowerCase()} '
            'movements.',
      ),
    for (final muscle in priorityMuscles.where(sessionMuscles.contains).take(2))
      RecommendationTag(
        '${muscle.label} priority',
        '${muscle.label} work comes first in this session.',
      ),
    RecommendationTag(
      sessionDuration.label,
      'Sized to fit ${sessionDuration.label}.',
    ),
  ];
}

/// Tags for one exercise, from the reasons it was chosen.
List<RecommendationTag> exerciseTags({
  required Exercise exercise,
  required List<MuscleGroup> priorityMuscles,
  required bool coversNewPattern,
  required ExperienceLevel experience,
  String? proportionReason,
}) {
  final hitsPriority = exercise.primaryMuscles.any(priorityMuscles.contains);

  return [
    if (hitsPriority)
      const RecommendationTag(
        'Priority muscle',
        'It trains one of the muscles you singled out.',
      ),
    for (final muscle in exercise.primaryMuscles.take(2))
      RecommendationTag(
        '${muscle.label} emphasis',
        'It trains ${muscle.label} as a main mover.',
      ),
    if (coversNewPattern &&
        exercise.movementPattern != MovementPattern.isolation &&
        exercise.movementPattern != MovementPattern.cardio)
      RecommendationTag(
        exercise.movementPattern.label,
        'It covers a movement pattern the session was missing.',
      ),
    const RecommendationTag(
      'Equipment match',
      'It needs nothing beyond the equipment you have.',
    ),
    if (exercise.experienceLevel == ExperienceLevel.beginner &&
        experience == ExperienceLevel.beginner)
      const RecommendationTag(
        'Beginner friendly',
        'Straightforward to learn and to set up.',
      ),
    if (proportionReason != null)
      RecommendationTag('Suits your proportions', proportionReason),
  ];
}

String _goalLabel(TrainingGoal goal) {
  switch (goal) {
    case TrainingGoal.buildMuscle:
      return 'Hypertrophy';
    case TrainingGoal.getStronger:
      return 'Strength';
    case TrainingGoal.loseFat:
      return 'Fat loss';
    case TrainingGoal.improveBodyComposition:
      return 'Body composition';
    case TrainingGoal.improveAthleticPerformance:
      return 'Athletic';
  }
}
